<?php $assistant=$ortho['assistant'] ?? []; $assistantStatus=$assistant['status'] ?? ['available'=>false,'message'=>'IA externa pendiente de configuración. No se han enviado datos clínicos a servicios externos.']; $proposals=$assistant['proposals'] ?? []; ?>
<div class="orth-section-intro"><div><h3>Asistente del expediente</h3><p>Organiza los hechos registrados y conserva la revisión del profesional.</p></div><span class="orth-status">IA externa pendiente</span></div>
<div class="orth-info"><?= icon('shield',20) ?><div><strong>Resumen de registros, sin IA externa</strong><p><?= e($assistantStatus['message'] ?? 'La integración de inteligencia artificial está pendiente. Esta herramienta recupera información existente; no realiza inferencias clínicas.') ?></p></div></div>
<?php if($canWrite): ?><section class="panel"><div class="orth-section-heading"><div><span class="orth-kicker">DOCUMENTACIÓN ASISTIDA CON DATOS DEL CASO</span><h3>Preparar un borrador de consulta</h3></div></div><form method="post" class="form-grid orth-panel-body" data-orth-dirty data-loading><?php $orthoFields('assistant_generate',$case); choose('kind','Contenido del borrador',['summary'=>'Resumen de registros clínicos','evolution'=>'Cambios documentados en controles','document'=>'Borrador de informe','question'=>'Consulta de información registrada'],'summary'); ?><p class="orth-help">Los datos ausentes se indican como no registrados. El contenido permanece como borrador hasta que lo revises.</p><?php area('prompt','Pregunta o propósito (opcional)'); ?><div class="orth-question-hints full"><span>Consultas disponibles:</span><?php foreach(['¿Cuándo fue el último control?','¿Qué procedimientos se registraron en la última visita?','¿Cuándo está programado el siguiente control?','¿Qué objetivos están registrados?'] as $question): ?><button class="orth-question" type="button" data-orth-question="<?= e($question) ?>"><?= e($question) ?></button><?php endforeach; ?></div><button class="button">Preparar borrador con los registros</button></form></section><?php endif; ?>
<section class="panel"><div class="orth-section-heading"><h3>Borradores y revisiones</h3><p>Una revisión nunca modifica las evoluciones originales.</p></div><?php if(!$proposals): $orthoEmpty('Sin borradores preparados','Consulta los registros del caso y revisa el contenido antes de incorporarlo a un documento.','file'); else: ?><div class="orth-records"><?php foreach($proposals as $proposal): $proposalStatus=$proposal['status'] ?? 'draft'; ?><details class="orth-record"<?= $proposalStatus==='draft'?' open':'' ?>><summary><span><strong><?= e($proposal['title'] ?? 'Resumen de registros') ?></strong><small><?= local_date($proposal['created_at'] ?? null) ?> · Sin IA externa</small></span><span class="orth-status <?= $proposalStatus==='accepted'?'active':'' ?>"><?= ['draft'=>'Borrador para revisión','accepted'=>'Validado por el profesional','discarded'=>'Descartado'][$proposalStatus] ?? e($proposalStatus) ?></span></summary><div class="orth-record-body"><?php if($canWrite && $proposalStatus==='draft'): ?><form method="post" class="form-grid" data-orth-dirty data-loading><?php $orthoFields('assistant_review',$case); ?><input type="hidden" name="proposal_id" value="<?= (int)$proposal['id'] ?>"><?php area('content','Contenido editable para revisión',$proposal['content'] ?? $proposal['draft_content'] ?? '',true); ?><label>Decisión<select name="decision"><option value="accepted">Validar e incorporar como documento auxiliar</option><option value="discarded">Descartar borrador</option></select></label><label class="orth-check full"><input type="checkbox" name="confirm_review" value="1">Confirmo que revisé el contenido y autorizo su validación profesional, si corresponde.</label><button class="button secondary">Guardar revisión</button></form><?php else: ?><div class="orth-assistant-content"><?= nl2br(e($proposal['reviewed_content'] ?? $proposal['content'] ?? $proposal['draft_content'] ?? '')) ?></div><?php endif; ?></div></details><?php endforeach; ?></div><?php endif; ?></section>
